using System.Security.Cryptography;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Diagnostics;
using Microsoft.Extensions.Logging.Abstractions;
using PdfSharpCore.Pdf;
using PropFlow.Modules.Authentication.Contracts;
using PropFlow.Modules.RemoteOnlineSign.Application;
using PropFlow.Modules.RemoteOnlineSign.Domain;
using PropFlow.Modules.RemoteOnlineSign.Infrastructure.Persistence;
using PropFlow.Modules.RemoteOnlineSign.Infrastructure.Storage;

namespace PropFlow.UnitTests;

public sealed class RemoteOnlineSignFinalizationTests
{
    [Fact] public async Task Storage_failure_after_otp_consumption_keeps_contract_pending_and_retry_completes() { await using var f=new Fixture(); var (c,s)=await f.PreparedAsync(); f.Store.FailDerived=true; var storageError=await Assert.ThrowsAsync<RemoteContractException>(()=>f.Service.VerifyAndFinalizeAsync(f.Resident,false,c.Id,new(s,"123456"),default)); Assert.Equal("pdf_storage_failed",storageError.Code); Assert.Equal(RemoteContractStatus.PENDING_RESIDENT_SIGNATURE,(await f.Db.Contracts.FindAsync(c.Id))!.Status); Assert.Empty(f.Db.Documents.Where(x=>x.IsFinal)); Assert.DoesNotContain(f.Db.Events,x=>x.Type=="CONTRACT_COMPLETED"); f.Store.FailDerived=false; var done=await f.Service.VerifyAndFinalizeAsync(f.Resident,false,c.Id,new(s,"ignored"),default); Assert.Equal("COMPLETED",done.Status); Assert.Single(f.Db.Documents.Where(x=>x.IsFinal)); }
    [Fact] public async Task Database_failure_after_final_upload_cleans_only_new_final_asset_and_never_completes() { await using var f=new Fixture(); var (c,s)=await f.PreparedAsync(); f.FailSave=true; await Assert.ThrowsAsync<InvalidOperationException>(()=>f.Service.VerifyAndFinalizeAsync(f.Resident,false,c.Id,new(s,"123456"),default)); Assert.Equal(RemoteContractStatus.PENDING_RESIDENT_SIGNATURE,(await f.Db.Contracts.FindAsync(c.Id))!.Status); Assert.Empty(f.Db.Documents.Where(x=>x.IsFinal)); Assert.Single(f.Store.Data); Assert.DoesNotContain(f.Db.Events,x=>x.Type=="CONTRACT_COMPLETED"); }
    [Fact] public async Task Completed_retry_is_idempotent_and_does_not_create_second_final_asset() { await using var f=new Fixture(); var(c,s)=await f.PreparedAsync(); await f.Service.VerifyAndFinalizeAsync(f.Resident,false,c.Id,new(s,"123456"),default); var assets=f.Store.Data.Count; var again=await f.Service.VerifyAndFinalizeAsync(f.Resident,false,c.Id,new(s,"anything"),default); Assert.Equal("COMPLETED",again.Status); Assert.Equal(assets,f.Store.Data.Count); Assert.Single(f.Db.Documents.Where(x=>x.IsFinal)); Assert.Single(f.Db.Events.Where(x=>x.Type=="CONTRACT_COMPLETED")); }
    private sealed class Fixture : IAsyncDisposable { public Guid Admin=Guid.NewGuid(); public Guid Resident=Guid.NewGuid(); public Store Store=new(); public RemoteOnlineSignDbContext Db; public RemoteContractService Service; private FaultSave fault=new(); public bool FailSave{set=>fault.Fail=value;} public Fixture(){Db=new(new DbContextOptionsBuilder<RemoteOnlineSignDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).ConfigureWarnings(w=>w.Ignore(InMemoryEventId.TransactionIgnoredWarning)).AddInterceptors(fault).Options);Service=new(Db,Store,new Otp(),new PdfSignatureStamper(),NullLogger<RemoteContractService>.Instance,new RemoteTestAccountAccess(),new RemoteTestAccountDirectory(),new RemoteTestResidentScope(),new RemoteContractCodeGenerator(Db));} public async Task<(RemoteContract,Guid)> PreparedAsync(){var c=new RemoteContract{CreatorId=Admin,ResidentId=Resident,SigningMode=RemoteSigningMode.PRE_SIGNED_INVESTOR,Status=RemoteContractStatus.DRAFT};Db.Contracts.Add(c);await Db.SaveChangesAsync();var p=Pdf();await Service.UploadOriginalAsync(Admin,c.Id,new MemoryStream(p),p.Length,default);await Service.SetFieldsAsync(Admin,c.Id,[new(SignatureRole.RESIDENT,1,10,10,100,30)],default);await Service.SendAsync(Admin,c.Id,new(),default);var q=await Service.BeginSigningAsync(Resident,false,c.Id,new(SignatureMethod.TYPE,null,"Resident","Arial"),default);return(c,q.SessionId);} public ValueTask DisposeAsync()=>Db.DisposeAsync(); }
    private sealed class FaultSave:SaveChangesInterceptor { public bool Fail; public override ValueTask<InterceptionResult<int>> SavingChangesAsync(DbContextEventData d,InterceptionResult<int> r,CancellationToken c=default){if(Fail){Fail=false;throw new InvalidOperationException("db fault");}return base.SavingChangesAsync(d,r,c);} }
    private sealed class Otp:IPrivilegedActionOtp { public Task<PrivilegedActionChallengeResult> RequestAsync(Guid u,string p,string b,CancellationToken c)=>Task.FromResult(new PrivilegedActionChallengeResult(Guid.NewGuid(),DateTimeOffset.UtcNow.AddMinutes(5),DateTimeOffset.UtcNow,"***")); public Task VerifyAsync(Guid u,Guid i,string p,string b,string code,CancellationToken c){if(code!="123456")throw new InvalidOperationException("otp");return Task.CompletedTask;} }
    private sealed class Store:IRemotePdfStorage { public bool FailDerived; public Dictionary<string,byte[]> Data=new(); public async Task<StoredPdf> PutOriginalAsync(Guid c,Stream s,long l,CancellationToken t)=>await Put(s,t); public async Task<StoredPdf> PutDerivedAsync(Guid c,string p,Stream s,long l,CancellationToken t){if(FailDerived)throw new IOException("storage");return await Put(s,t);} private async Task<StoredPdf> Put(Stream s,CancellationToken t){using var m=new MemoryStream();await s.CopyToAsync(m,t);var b=m.ToArray();var k=Guid.NewGuid().ToString("N");Data[k]=b;return new(k,Convert.ToHexString(SHA256.HashData(b)).ToLowerInvariant(),b.Length);} public Task<Stream> OpenReadAsync(string k,CancellationToken t)=>Task.FromResult<Stream>(new MemoryStream(Data[k])); public Task<bool> ExistsWithHashAsync(string k,string h,CancellationToken t)=>Task.FromResult(true); public Task DeleteIfUnreferencedAsync(string k,CancellationToken t){Data.Remove(k);return Task.CompletedTask;} }
    private static byte[] Pdf(){using var d=new PdfDocument();d.AddPage();using var s=new MemoryStream();d.Save(s,false);return s.ToArray();}
}
